package com.booktracker.servlet;
import com.booktracker.dao.TrackerDAO; import jakarta.servlet.*; import jakarta.servlet.http.*; import jakarta.servlet.annotation.*; import java.io.IOException; import java.sql.*;
@WebServlet("/action") public class ActionServlet extends HttpServlet { private final TrackerDAO dao=new TrackerDAO(); protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{req.setCharacterEncoding("UTF-8");String action=req.getParameter("action");try{if("addBook".equals(action)){String title=required(req,"title"),author=required(req,"author"),isbn=req.getParameter("isbn");int copies=Integer.parseInt(required(req,"copies"));if(copies<1)throw new IllegalArgumentException("Copies must be at least 1.");dao.addBook(title,author,isbn,copies);msg(req,"Book added successfully.");}else if("addBorrower".equals(action)){dao.addBorrower(required(req,"fullName"),req.getParameter("email"),req.getParameter("phone"));msg(req,"Borrower added successfully.");}else if("issueBook".equals(action)){int bookId=Integer.parseInt(required(req,"bookId")),borrowerId=Integer.parseInt(required(req,"borrowerId"));Date issue=Date.valueOf(required(req,"issueDate")),due=Date.valueOf(required(req,"dueDate"));if(due.before(issue))throw new IllegalArgumentException("Due date cannot be before issue date.");dao.issueBook(bookId,borrowerId,issue,due);msg(req,"Book issued successfully.");}else if("returnBook".equals(action)){dao.returnBook(Integer.parseInt(required(req,"issueId")));msg(req,"Book returned successfully.");}else throw new IllegalArgumentException("Unknown action.");}catch(IllegalArgumentException e){req.getSession().setAttribute("error",e.getMessage()==null?"Please check the entered values.":e.getMessage());}catch(SQLException e){String m=e.getMessage();req.getSession().setAttribute("error",m!=null&&m.contains("Duplicate")?"That ISBN is already registered.":m==null?"Database operation failed.":m);}resp.sendRedirect(req.getContextPath()+"/");}private String required(HttpServletRequest r,String k){String v=r.getParameter(k);if(v==null||v.trim().isEmpty())throw new IllegalArgumentException("Please fill all required fields.");return v.trim();}private void msg(HttpServletRequest r,String m){r.getSession().setAttribute("message",m);} }
